def is_cube(n):
    if n == 0:
        return True, 0

    # Handle negative numbers by checking the cube root of the absolute value
    sign = 1
    if n < 0:
        sign = -1
        n = -n

    # Approximate cube root
    cbrt = round(n**(1/3))

    # Check if the rounded value cubed equals n
    if abs(cbrt**3 - n) < 1e-9:
        return True, sign * cbrt
    return False, None

def P(x):
    return (8 * x - 41) * (x + 3)**2

solutions = []
for x in range(-30, 31):
    val = P(x)
    is_perfect_cube, root = is_cube(val)
    if is_perfect_cube:
        solutions.append((x, root))

print(solutions)
